import{_ as n,I as t,o as r,c as d,b6 as i,j as o,J as e,w as h}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"Spring Boot 電影推薦系統開發實戰","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/stage-2/assignments/movie-recommendation-springboot/index.md","filePath":"zh-tw/stage-2/assignments/movie-recommendation-springboot/index.md"}'),p={name:"zh-tw/stage-2/assignments/movie-recommendation-springboot/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),s=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=i('<h1 id="spring-boot-電影推薦系統開發實戰" tabindex="-1">Spring Boot 電影推薦系統開發實戰 <a class="header-anchor" href="#spring-boot-電影推薦系統開發實戰" aria-label="Permalink to “Spring Boot 電影推薦系統開發實戰”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本實戰項目要求你圍繞一份真實的 PRD，使用 Spring Boot 完成一個帶推薦能力的電影網站。這個項目的核心挑戰在於：它不是簡單的增刪改查，而是需要你思考&quot;用戶行為如何影響推薦結果&quot;以及&quot;推薦如何可解釋&quot;。</p><p>這是 Stage 2 的綜合實戰環節。你將第一次接觸&quot;內容 + 行為 + 推薦&quot;型產品的開發模式，這種模式在電商、內容平臺、個性化 Feed 等場景中非常常見。</p><h2 id="前置知識" tabindex="-1">前置知識 <a class="header-anchor" href="#前置知識" aria-label="Permalink to “前置知識”">​</a></h2><p>在開始本項目之前，你應該已經掌握以下內容：</p><ul><li>前端頁面設計與組件庫使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">現代組件庫</a>）</li><li>後端接口設計與開發（<a href="./../../backend/ai-interface-code/">接口程式碼編寫</a>）</li><li>資料庫基礎與 Supabase（<a href="./../../backend/database-supabase/">從資料庫到 Supabase</a>）</li><li>Git 工作流與部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 應用</a>）</li></ul><h2 id="學習目標" tabindex="-1">學習目標 <a class="header-anchor" href="#學習目標" aria-label="Permalink to “學習目標”">​</a></h2><p>完成本實戰後，你將能夠：</p><ol><li>閱讀 PRD 並從中提取推薦系統的開發任務清單</li><li>使用 Spring Boot 搭建後端項目並實現 RESTful API</li><li>設計&quot;用戶行為 → 推薦&quot;的完整資料鏈路</li><li>實現可解釋的推薦邏輯</li><li>完成端到端聯調，交付可演示的產品原型</li></ol><h2 id="項目簡介" tabindex="-1">項目簡介 <a class="header-anchor" href="#項目簡介" aria-label="Permalink to “項目簡介”">​</a></h2><p>你要構建的產品是一個帶推薦能力的電影網站：</p><table tabindex="0"><thead><tr><th>功能</th><th>描述</th></tr></thead><tbody><tr><td><strong>瀏覽與搜索</strong></td><td>用戶可以瀏覽和搜索電影</td></tr><tr><td><strong>評分與收藏</strong></td><td>用戶可以給電影評分、添加收藏</td></tr><tr><td><strong>個性化推薦</strong></td><td>系統根據用戶行為給出推薦結果</td></tr><tr><td><strong>管理後臺</strong></td><td>管理員維護電影資料、查看推薦效果</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本項目的需求文檔在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-tw/stage-2/assignments/movie-recommendation-springboot/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',14)),o("div",c,[e(s,null,{default:h(()=>[e(l,{active:0,items:[{title:"需求分析",description:"閱讀 PRD，明確推薦策略、行為資料和後臺範圍"},{title:"搭建骨架",description:"用 AI 生成列表頁、詳情頁、推薦頁和後臺頁"},{title:"迭代開發",description:"補充推薦邏輯、行為記錄和後臺管理"},{title:"聯調上線",description:"端到端跑通，部署並準備演示"}]})]),_:1})]),a[1]||(a[1]=i(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-閱讀-prd" tabindex="-1">1.1 閱讀 PRD <a class="header-anchor" href="#_1-1-閱讀-prd" aria-label="Permalink to “1.1 閱讀 PRD”">​</a></h3><p>打開 PRD 文檔，重點回答以下問題：</p><ul><li>推薦策略是什麼？第一版是否使用可解釋版本（如基於評分相似度）？</li><li>用戶行為資料要存哪些？（評分、收藏、瀏覽記錄等）</li><li>管理員需要看哪些推薦效果指標？</li><li>頁面清單是否完整？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上問題沒有明確答案，不要開始寫程式碼。需求理解不清楚是導致返工的最常見原因。</p></div><h3 id="_1-2-確認系統架構" tabindex="-1">1.2 確認系統架構 <a class="header-anchor" href="#_1-2-確認系統架構" aria-label="Permalink to “1.2 確認系統架構”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;前端頁面&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; auth[&quot;用戶鑑權&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; movie[&quot;電影列表 / 詳情&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; behavior[&quot;評分 / 收藏&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  behavior --&gt; reco[&quot;推薦邏輯&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  reco --&gt; db[&quot;資料庫&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin[&quot;後臺管理&quot;] --&gt; db</span></span></code></pre></div><h2 id="第二部分-搭建項目骨架" tabindex="-1">第二部分：搭建項目骨架 <a class="header-anchor" href="#第二部分-搭建項目骨架" aria-label="Permalink to “第二部分：搭建項目骨架”">​</a></h2><h3 id="_2-1-生成前端頁面" tabindex="-1">2.1 生成前端頁面 <a class="header-anchor" href="#_2-1-生成前端頁面" aria-label="Permalink to “2.1 生成前端頁面”">​</a></h3><p>提示詞參考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請基於當前 PRD，幫我生成一個 Spring Boot 電影推薦系統的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 頁面包括：首頁、電影列表、電影詳情、推薦頁、個人中心、後臺管理</span></span>
<span class="line"><span>2. 先只生成頁面結構和假資料，不接真實接口</span></span>
<span class="line"><span>3. 風格要像真實內容產品，而不是課堂 demo</span></span></code></pre></div><h3 id="_2-2-驗證頁面結構" tabindex="-1">2.2 驗證頁面結構 <a class="header-anchor" href="#_2-2-驗證頁面結構" aria-label="Permalink to “2.2 驗證頁面結構”">​</a></h3><p>逐項檢查：</p><ul><li>[ ] 電影列表頁支持搜索和篩選</li><li>[ ] 電影詳情頁包含評分和收藏按鈕</li><li>[ ] 推薦頁能展示推薦結果和推薦理由</li><li>[ ] 管理後臺能展示電影資料和推薦效果</li></ul><h2 id="第三部分-迭代開發" tabindex="-1">第三部分：迭代開發 <a class="header-anchor" href="#第三部分-迭代開發" aria-label="Permalink to “第三部分：迭代開發”">​</a></h2><h3 id="_3-1-按模塊推進" tabindex="-1">3.1 按模塊推進 <a class="header-anchor" href="#_3-1-按模塊推進" aria-label="Permalink to “3.1 按模塊推進”">​</a></h3><ol><li><strong>Spring Boot 項目搭建</strong>：項目結構、資料庫配置、基礎 CRUD</li><li><strong>電影資料管理</strong>：電影列表、詳情、搜索接口</li><li><strong>用戶行為</strong>：評分、收藏接口，行為資料寫入</li><li><strong>推薦邏輯</strong>：基於用戶行為的推薦算法實現</li><li><strong>推薦展示</strong>：推薦結果展示，包含推薦理由</li><li><strong>管理後臺</strong>：電影資料維護、推薦效果查看</li></ol><h3 id="_3-2-模塊自檢" tabindex="-1">3.2 模塊自檢 <a class="header-anchor" href="#_3-2-模塊自檢" aria-label="Permalink to “3.2 模塊自檢”">​</a></h3><table tabindex="0"><thead><tr><th>檢查項</th><th>驗證方法</th></tr></thead><tbody><tr><td>基礎功能</td><td>列表、詳情、評分、收藏是否閉環</td></tr><tr><td>推薦聯動</td><td>用戶行為是否影響推薦結果</td></tr><tr><td>推薦可解釋性</td><td>用戶能理解為什麼被推薦這些電影</td></tr><tr><td>後臺資料</td><td>管理員能查看電影資料和推薦效果</td></tr></tbody></table><h2 id="第四部分-聯調與上線" tabindex="-1">第四部分：聯調與上線 <a class="header-anchor" href="#第四部分-聯調與上線" aria-label="Permalink to “第四部分：聯調與上線”">​</a></h2><h3 id="_4-1-端到端測試" tabindex="-1">4.1 端到端測試 <a class="header-anchor" href="#_4-1-端到端測試" aria-label="Permalink to “4.1 端到端測試”">​</a></h3><p>至少驗證以下場景：</p><ul><li>瀏覽電影 → 評分 → 收藏 → 查看推薦頁，確認推薦結果發生變化</li><li>管理員登錄 → 添加電影 → 查看推薦效果統計</li></ul><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本項目後，你需要提交以下內容：</p><ul><li>[ ] 可訪問的線上演示鏈接</li><li>[ ] 源碼倉庫鏈接（含 README）</li><li>[ ] PRD 文檔</li><li>[ ] 核心頁面截圖（電影列表、電影詳情、推薦頁、管理後臺）</li><li>[ ] 60 秒演示影片</li></ul><h2 id="評分標準" tabindex="-1">評分標準 <a class="header-anchor" href="#評分標準" aria-label="Permalink to “評分標準”">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>基本要求</th><th>進階要求</th></tr></thead><tbody><tr><td>PRD 對齊</td><td>頁面、功能、資料結構基本符合 PRD</td><td>能清晰說明設計決策</td></tr><tr><td>產品閉環</td><td>瀏覽 → 評分 → 收藏 → 推薦可跑通</td><td>評分行為明顯影響推薦結果</td></tr><tr><td>推薦質量</td><td>推薦結果合理、推薦理由可解釋</td><td>支持多種推薦策略</td></tr><tr><td>後臺能力</td><td>電影資料和推薦效果可查看</td><td>有推薦準確率等統計指標</td></tr><tr><td>工程完整度</td><td>前端、Spring Boot 後端、資料庫鏈路已接通</td><td>推薦接口有緩存或性能優化</td></tr></tbody></table><h2 id="參考資料" tabindex="-1">參考資料 <a class="header-anchor" href="#參考資料" aria-label="Permalink to “參考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/modern-component-library/">使用現代組件庫更新你的界面</a></li><li><a href="./../../backend/database-supabase/">從資料庫到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型輔助編寫接口程式碼與接口文檔</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 應用</a></li></ul>`,30))])}const E=n(p,[["render",b]]);export{P as __pageData,E as default};
